const cmds=[
["datum","nl -ba AlgebraicJacobian/Picard/Pic0RankOneNativePresentationDatum.lean | sed -n '35,190p'"],
["split","nl -ba AlgebraicJacobian/Picard/Pic0RankOneNativePresentationSplit.lean | sed -n '55,135p'"],
["isopen","nl -ba AlgebraicJacobian/Picard/Pic0ChartLocusIsOpen.lean | sed -n '250,340p'"],
["gentest","nl -ba AlgebraicJacobian/Picard/Pic0ChartLocusGeneralTest.lean | sed -n '35,230p'"],
["defs","rg -n -C 5 'def IsChartDatumPresentation|theorem .*isChartDatumPresentation|IsChartDatumPresentation' AlgebraicJacobian/Picard/*.lean | head -240"],
["quot","rg -n -C 3 'isQuotientMap_of_generalizingMap|GeneralizingMap|generalizingMap|isOpen.*preimage' AlgebraicJacobian Mathlib 2>/dev/null | head -240"]
