const cmds=[
["cover","rg -n -C 4 'EtaleCover.*(surj|surjective|faithfully|comap)|cover.*isOpenMap|carrier.*isOpenMap|PrimeSpectrum.comap.*cover' AlgebraicJacobian Mathlib 2>/dev/null | head -300"],
["mathlib","rg -n 'isQuotientMap_of_generalizingMap' .lake/packages/mathlib/Mathlib | head -40"],
