["coverdef","rg -n 'structure EtaleCover|def EtaleCover|namespace Algebra.EtaleCover' .lake/packages/mathlib/Mathlib AlgebraicJacobian | head -120"]
];
const rs=await Promise.all(cmds.map(([n,cmd])=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`### ${cmds[i][0]}\n${r.output}`));

