["fibre","rg -n '^(noncomputable )?(def|theorem|lemma|structure) |open|IsOpen|extension|invariant' AlgebraicJacobian/Picard/Pic0ChartLocusFibreField.lean | head -n 220"],
["iso","rg -n '^(noncomputable )?(def|theorem|lemma|structure) |open|IsOpen|invariant' AlgebraicJacobian/Picard/Pic0ChartLocusIsoInvariance.lean | tail -n 180"],
